"""Query Loki for last user prompt per Claude Code session."""

import json
import logging
import re
import time
import urllib.parse
import urllib.request

from claude_dashboard import config

logger = logging.getLogger(__name__)

_TIMEOUT_SECONDS = 3

_LOOKBACK_SECONDS = 86400  # 24 hours

_XML_BLOCK_RE = re.compile(r"<([a-zA-Z][\w-]*)[\s>].*?</\1>", re.DOTALL)
_ORPHAN_TAGS_RE = re.compile(r"<[^>]+>")


def _extract_user_text(text: str) -> str:
    """Strip XML blocks and tags, keeping only user-typed text.

    Claude Code OTEL prompts mix user input with system-injected XML
    (hooks, task notifications, command metadata). User text is never
    wrapped in XML tags — stripping all XML blocks and orphan tags
    isolates it without maintaining a tag allowlist.
    """
    text = _XML_BLOCK_RE.sub("", text)
    text = _ORPHAN_TAGS_RE.sub("", text)
    return text.strip()


def _truncate(text: str, *, max_chars: int) -> str:
    """Collapse whitespace and truncate to max_chars with ellipsis."""
    collapsed = " ".join(text.split())
    if len(collapsed) <= max_chars:
        return collapsed
    return collapsed[: max_chars - 1] + "…"


def _extract_prompts(results: list[dict], *, key: str, max_chars: int) -> dict[str, str]:
    """Extract prompt text from Loki streams, keyed by the given label.

    Results are sorted newest-first by observed_timestamp before
    extraction. Loki's direction=backward orders entries within each
    stream but does NOT guarantee cross-stream ordering — each unique
    structured-metadata combination is a separate stream.
    """
    sorted_results = sorted(
        results,
        key=lambda s: int(s.get("stream", {}).get("observed_timestamp", "0")),
        reverse=True,
    )
    prompts: dict[str, str] = {}
    for stream in sorted_results:
        labels = stream.get("stream", {})
        match_val = labels.get(key, "")
        if not match_val or match_val in prompts:
            continue
        raw_prompt = labels.get("prompt", "")
        if not raw_prompt:
            logger.debug("loki stream %s=%s: no prompt label", key, match_val)
            continue
        prompt_text = _extract_user_text(raw_prompt)
        if not prompt_text:
            logger.debug("loki stream %s=%s: empty after xml strip", key, match_val)
            continue
        prompts[match_val] = _truncate(prompt_text, max_chars=max_chars)
        logger.debug("loki prompt %s=%s text=%s", key, match_val, prompts[match_val][:60])
    return prompts


def poll_last_prompts(
    *,
    loki_url: str,
    session_ids: list[str] | None = None,
    sandbox_names: list[str] | None = None,
    max_chars: int = config.DEFAULT_TOOLTIP_MAX_CHARS,
) -> dict[str, str]:
    """Query Loki for the most recent user_prompt event per session.

    Returns dict mapping identifier to truncated prompt text.
    Local sessions are matched by ``session_id``; sandboxes by
    ``sandbox_openshell_name`` (``sb-<hash>``), the only label that joins
    telemetry to ``openshell sandbox list``, which is where sandbox rows get
    their session_id. Never match sandboxes on ``host_name`` — that is the
    creating machine, not the sandbox.

    Results are keyed by session_id for local sessions and by
    sandbox_openshell_name for sandboxes — the caller maps these back to PIDs.
    """
    prompts: dict[str, str] = {}

    if session_ids:
        query = (
            '{service_name="claude-code"}'
            ' | event_name = "user_prompt"'
            f' | session_id =~ "{"|".join(session_ids)}"'
        )
        logger.debug("loki session query: %s", query)
        try:
            results = _query_loki(loki_url=loki_url, query=query, limit=len(session_ids) * 20)
            logger.debug("loki session results: %d streams", len(results))
            prompts.update(_extract_prompts(results, key="session_id", max_chars=max_chars))
        except Exception:
            logger.debug("loki session query failed", exc_info=True)

    if sandbox_names:
        query = (
            '{service_name="claude-code"}'
            ' | event_name = "user_prompt"'
            f' | sandbox_openshell_name =~ "{"|".join(sandbox_names)}"'
        )
        logger.debug("loki sandbox query: %s", query)
        try:
            results = _query_loki(loki_url=loki_url, query=query, limit=len(sandbox_names) * 20)
            logger.debug("loki sandbox results: %d streams", len(results))
            prompts.update(
                _extract_prompts(results, key="sandbox_openshell_name", max_chars=max_chars)
            )
        except Exception:
            logger.debug("loki sandbox query failed", exc_info=True)

    return prompts


def _query_loki(*, loki_url: str, query: str, limit: int = 100) -> list[dict]:
    """Run a Loki query_range and return stream results (newest first)."""
    now = time.time()
    params = urllib.parse.urlencode(
        {
            "query": query,
            "direction": "backward",
            "limit": str(limit),
            "start": str(int((now - _LOOKBACK_SECONDS) * 1e9)),
            "end": str(int(now * 1e9)),
        }
    )
    url = f"{loki_url}/loki/api/v1/query_range?{params}"
    logger.debug("loki HTTP GET %s", url)
    try:
        req = urllib.request.Request(url)
        with urllib.request.urlopen(req, timeout=_TIMEOUT_SECONDS) as resp:
            raw = resp.read()
            data = json.loads(raw)
            if data.get("status") != "success":
                logger.debug("loki query status=%s data=%s", data.get("status"), raw[:200])
                return []
            result = data.get("data", {}).get("result", [])
            logger.debug("loki HTTP success: %d streams", len(result))
            return result
    except Exception as exc:
        logger.debug("loki query failed: %s", exc)
        return []
